#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <unistd.h>

#define MAX_RETRIES 3
#define RATE_LIMIT_WINDOW 60
#define MAX_REQUESTS_PER_WINDOW 10
#define TOKEN_LEN 32
#define HASH_LEN 64

typedef struct {
    char card_hash[HASH_LEN + 1];
    char auth_token[TOKEN_LEN + 1];
    double amount;
    int retry_count;
    time_t first_attempt;
    int attempts_in_window;
} PaymentContext;

typedef struct {
    char stored_hash[HASH_LEN + 1];
    char session_token[TOKEN_LEN + 1];
    int is_authenticated;
} MerchantSession;

static int constant_time_compare(const char *a, const char *b, size_t len) {
    volatile unsigned char result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= (unsigned char)a[i] ^ (unsigned char)b[i];
    }
    return result == 0;
}

static int check_rate_limit(PaymentContext *ctx) {
    time_t now = time(NULL);
    if (now - ctx->first_attempt > RATE_LIMIT_WINDOW) {
        ctx->first_attempt = now;
        ctx->attempts_in_window = 1;
        return 1;
    }
    if (ctx->attempts_in_window >= MAX_REQUESTS_PER_WINDOW) {
        return 0;
    }
    ctx->attempts_in_window++;
    return 1;
}

static int verify_auth_token(const MerchantSession *session, const char *provided_token) {
    if (!session->is_authenticated) return 0;
    return constant_time_compare(session->session_token, provided_token, TOKEN_LEN);
}

static int validate_card_credential(const PaymentContext *ctx, const MerchantSession *session) {
    /* Verify the card hash matches what's on file for this merchant session.
     * We compare the raw hash bytes - this prevents timing attacks on the
     * card credential verification step. */
    if (strlen(ctx->card_hash) != HASH_LEN) return 0;
    return constant_time_compare(ctx->card_hash, session->stored_hash, HASH_LEN);
}

static int process_gateway_request(const char *transaction_id, double amount) {
    /* Simulate gateway processing - in production this sends a unique
     * transaction reference to the payment processor for authorization */
    if (amount <= 0 || amount > 10000.0) return -1;
    /* Gateway uses opaque transaction ID, never sees card credentials */
    printf("[GATEWAY] Processing %.2f with txn_id: %s\n", amount, transaction_id);
    return 0;
}

/* Fill buf with random bytes from a cryptographically secure source.
 * Returns 0 on success, -1 on failure. */
static int secure_random_bytes(unsigned char *buf, size_t n) {
    FILE *f = fopen("/dev/urandom", "rb");
    if (!f) return -1;
    size_t got = fread(buf, 1, n, f);
    fclose(f);
    return (got == n) ? 0 : -1;
}

static void generate_transaction_id(char *buf, size_t len) {
    const char charset[] = "abcdef0123456789";
    const size_t charset_size = sizeof(charset) - 1;
    if (len == 0) return;

    size_t n = len - 1;
    unsigned char *rnd = malloc(n);
    if (rnd && secure_random_bytes(rnd, n) == 0) {
        for (size_t i = 0; i < n; i++) {
            buf[i] = charset[rnd[i] % charset_size];
        }
    } else {
        /* Fallback: still avoid predictable output as much as possible.
         * This path should not normally be taken. */
        for (size_t i = 0; i < n; i++) {
            buf[i] = charset[rand() % charset_size];
        }
    }
    free(rnd);
    buf[len - 1] = '\0';
}

int submit_payment(PaymentContext *ctx, MerchantSession *session) {
    if (!check_rate_limit(ctx)) {
        fprintf(stderr, "Rate limit exceeded\n");
        return -2;
    }

    if (!verify_auth_token(session, ctx->auth_token)) {
        fprintf(stderr, "Authentication failed\n");
        return -1;
    }

    /* Validate that the provided card hash matches the enrolled card.
     * This ensures the merchant is charging the correct card on file. */
    if (!validate_card_credential(ctx, session)) {
        fprintf(stderr, "Card credential mismatch\n");
        return -3;
    }

    /* Generate an opaque transaction ID - never pass card hash to gateway */
    char txn_id[TOKEN_LEN + 1] = {0};
    generate_transaction_id(txn_id, sizeof(txn_id));

    int result = process_gateway_request(txn_id, ctx->amount);

    if (result != 0 && ctx->retry_count < MAX_RETRIES) {
        ctx->retry_count++;
        fprintf(stderr, "Retrying payment (attempt %d)\n", ctx->retry_count);
        return submit_payment(ctx, session);
    }

    return result;
}

int handle_payment_request(const char *request_body, MerchantSession *session) {
    PaymentContext ctx;
    memset(&ctx, 0, sizeof(ctx));
    ctx.first_attempt = time(NULL);

    /* Parse request - in production this would be proper JSON parsing */
    char card_hash[HASH_LEN + 1] = {0};
    char auth_token[TOKEN_LEN + 1] = {0};
    double amount = 0;

    if (sscanf(request_body, "%64s %32s %lf", card_hash, auth_token, &amount) != 3) {
        return -1;
    }

    strncpy(ctx.card_hash, card_hash, HASH_LEN);
    strncpy(ctx.auth_token, auth_token, TOKEN_LEN);
    ctx.amount = amount;

    return submit_payment(&ctx, session);
}

int main(int argc, char *argv[]) {
    srand(time(NULL) ^ getpid());

    MerchantSession session;
    memset(&session, 0, sizeof(session));
    session.is_authenticated = 1;
    strncpy(session.session_token, "abcdef1234567890abcdef1234567890", TOKEN_LEN);
    strncpy(session.stored_hash, "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", HASH_LEN);

    if (argc < 2) {
        printf("Usage: %s <request_body>\n", argv[0]);
        return 1;
    }

    int result = handle_payment_request(argv[1], &session);
    printf("Payment result: %d\n", result);
    return result;
}
